-- =====================================================================
-- 20261115090000_student_ai_evaluation.sql
--
-- AI evaluation of written answers (lead, 15 Nov: "make an OpenAI call in the
-- background; question + user answer are sent as context; the report is
-- generated by AI like the MCQ one").
--
-- How it works
--   1. Submitting a test already leaves short / long / subjective answers
--      "pending" in the stored report (adm_finalize_attempt, unchanged).
--   2. The student's report page calls the Edge Function evaluate-subjective.
--      It claims the job with student_ai_eval_request (the caller must own the
--      attempt; one job per attempt, at most 3 tries; a job stuck "running"
--      for 3 minutes can be claimed again), answers at once and calls OpenAI
--      in the background.
--   3. With the service role it reads adm_ai_eval_context (question, marks,
--      model answer, marking guide, the student's answer; no name or email)
--      and saves the result with adm_ai_eval_complete, or adm_ai_eval_fail.
--      Neither is callable by students, so the marks and the model answers
--      never pass through the browser.
--   4. adm_ai_eval_complete grades the pending rows (marks clamped to 0..the
--      question's marks; status correct / partial / incorrect), writes
--      quiz_answers.points_earned / is_correct and the attempt's score,
--      max_score, percentage and passed, rebuilds the report's summary,
--      breakdowns, strengths / weaknesses and comparison, and adds the AI's
--      feedback (per question, and an overall "ai" section).
--   5. student_ai_eval_status lets the report page show progress.
--
-- Also
--   * Short answer, long answer and subjective questions can be created,
--     edited, imported and copied again: adm_assert_question_type_allowed,
--     adm_insert_questions_bulk, update_question and adm_copy_quiz lose the
--     20261027090000 "coming soon" guard.
--   * adm_report_bucket counts 'partial' rows.
--
-- New: ai_attempt_evaluations (ours; RLS on, no policies, no grants).
-- Replaced (each edit marked "-- 20261115090000", the rest verbatim from the
-- file named above it): adm_assert_question_type_allowed,
-- adm_insert_questions_bulk, update_question, adm_copy_quiz, adm_report_bucket.
-- Lead objects: quiz_answers (update points_earned / is_correct of the
-- graded rows) and quiz_attempts (update score, max_score, percentage,
-- passed), the same columns adm_finalize_attempt writes. No schema, RLS or
-- policy change.
--
-- ROLLBACK
--   scripts/rollback_20261115090000_student_ai_evaluation.sql
-- =====================================================================
set search_path = public, extensions;

-- --------------------------------------------------------------- preflight
do $pre$
declare
  v_problems text[] := '{}';
  v_sig      text;
begin
  foreach v_sig in array array[
    'public.adm_student_uid()', 'public.adm_question_is_subjective(uuid)', 'public.adm_finalize_attempt(uuid,text)',
    'public.adm_assert_question_type_allowed(text)', 'public.adm_insert_questions_bulk(uuid,jsonb,text)',
    'public.update_question(uuid,jsonb)', 'public.adm_copy_quiz(uuid,uuid,integer,text)', 'public.adm_report_bucket(jsonb)']
  loop
    if to_regprocedure(v_sig) is null then
      v_problems := v_problems || format('missing %s (apply the earlier migrations first)', v_sig);
    end if;
  end loop;
  foreach v_sig in array array['student_ai_eval_request', 'student_ai_eval_status', 'adm_ai_eval_context',
                               'adm_ai_eval_complete', 'adm_ai_eval_fail'] loop
    if exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                where n.nspname = 'public' and p.proname = v_sig) then
      v_problems := v_problems || format('function public.%s already exists', v_sig);
    end if;
  end loop;
  if to_regclass('public.ai_attempt_evaluations') is not null then
    v_problems := v_problems || 'table public.ai_attempt_evaluations already exists'::text;
  end if;
  if to_regclass('public.attempt_reports') is null then
    v_problems := v_problems || 'missing public.attempt_reports'::text;
  end if;
  if cardinality(v_problems) > 0 then
    raise exception 'AI evaluation preflight: %', array_to_string(v_problems, '; ');
  end if;
end $pre$;


-- adm_assert_question_type_allowed: from 20261027090000_admin_block_subjective.sql
create or replace function public.adm_assert_question_type_allowed(p_type text) returns void
language plpgsql immutable set search_path = public, extensions as $$
begin
  -- 20261115090000: short answer, long answer and subjective questions are
  -- allowed again; their answers are graded by AI (evaluate-subjective).
  return;
end $$;

-- adm_insert_questions_bulk: from 20261029110000_admin_test_assets.sql
create or replace function public.adm_insert_questions_bulk(p_quiz uuid, p_questions jsonb, p_source text default 'manual')
returns int
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_bad record;
  v_n   int;
begin
  if jsonb_typeof(p_questions) is distinct from 'array' then return 0; end if;

  select x.v_type, public.adm_map_question_type(x.v_type) as v_lead into v_bad
    from (select e.ord, e.q,
                 lower(coalesce(nullif(btrim(coalesce(e.q ->> 'type', '')), ''), 'objective')) as v_type,
                 coalesce(nullif(btrim(coalesce(e.q ->> 'text', '')), ''), nullif(btrim(coalesce(e.q ->> 'body', '')), '')) as v_text
            from jsonb_array_elements(p_questions) with ordinality as e(q, ord)) x
   where x.v_text is not null
     and (public.adm_map_question_type(x.v_type) is null
          or (public.adm_map_question_type(x.v_type) = 'fill_in_blank' and public.adm_text_answer(x.q) = 'Manual grading: see rubric'))
   order by x.ord
   limit 1;
  if found then
    if v_bad.v_lead is null then
      raise exception 'Unsupported question type: %', v_bad.v_type using errcode = '22023';
    end if;
    perform public.adm_assert_question_type_allowed(v_bad.v_type);
    raise exception 'Fill-in-the-blank questions need an accepted answer.' using errcode = '22023';
  end if;

  with src as materialized (
    select gen_random_uuid() as id, x.q, x.v_text, x.v_type, public.adm_map_question_type(x.v_type) as v_lead,
           case when x.v_diff in ('easy', 'medium', 'hard') then x.v_diff else 'medium' end as v_diff,
           case when x.v_source in ('manual', 'ai', 'csv', 'duplicate', 'paste') then x.v_source else 'manual' end as v_source,
           ts.id as section_id,
           row_number() over (order by x.ord)::int as pos
      from (select e.ord, e.q,
                   coalesce(nullif(btrim(coalesce(e.q ->> 'text', '')), ''), nullif(btrim(coalesce(e.q ->> 'body', '')), '')) as v_text,
                   lower(coalesce(nullif(btrim(coalesce(e.q ->> 'type', '')), ''), 'objective')) as v_type,
                   lower(coalesce(nullif(btrim(coalesce(e.q ->> 'difficulty', '')), ''), 'medium')) as v_diff,
                   coalesce(nullif(e.q ->> 'source', ''), p_source, 'manual') as v_source
              from jsonb_array_elements(p_questions) with ordinality as e(q, ord)) x
      left join public.test_sections ts
        on ts.quiz_id = p_quiz and ts.position = nullif(x.q ->> 'sectionPosition', '')::int
     where x.v_text is not null
  ),
  ins_q as (
    insert into public.quiz_questions (id, quiz_id, question_text, question_type, points, explanation, sort_order)
    select src.id, p_quiz, src.v_text, src.v_lead, coalesce(nullif(src.q ->> 'marks', '')::numeric, 4),
           nullif(btrim(coalesce(src.q ->> 'explanation', '')), ''), src.pos
      from src
    returning 1
  ),
  ins_a as (
    insert into public.quiz_question_admin
      (question_id, admin_type, needs_manual_grading, section_id, negative_marks, difficulty, subject, topic,
       image_path, image_alt, answer_instructions, source, ai_job_id)
    select src.id, src.v_type, src.v_type in ('subjective', 'long_answer', 'descriptive'), src.section_id,
           greatest(coalesce(nullif(src.q ->> 'negativeMarks', '')::numeric, nullif(src.q ->> 'negative_marks', '')::numeric, 0), 0),
           src.v_diff, nullif(btrim(coalesce(src.q ->> 'subject', '')), ''), nullif(btrim(coalesce(src.q ->> 'topic', '')), ''),
           nullif(coalesce(src.q ->> 'image', src.q ->> 'image_path', ''), ''),   -- 20261029110000: checked by the caller
           left(nullif(btrim(coalesce(src.q ->> 'imageAlt', src.q ->> 'image_alt', '')), ''), 300),
           coalesce(nullif(src.q ->> 'answerInstructions', ''), nullif(src.q ->> 'rubric', ''), nullif(src.q ->> 'answer_instructions', '')),
           src.v_source, nullif(src.q ->> 'aiJobId', '')::uuid
      from src
  ),
  ins_o as (
    insert into public.quiz_question_options (question_id, option_text, is_correct, sort_order)
    select src.id, o.option_text, o.is_correct, o.sort_order
      from src cross join lateral public.adm_question_options(src.v_lead, src.q) o
  )
  select count(*) into v_n from ins_q;
  return v_n;
end $$;

-- update_question: from 20261029110000_admin_test_assets.sql
create or replace function public.update_question(p_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_quiz        uuid;
  v_cur_lead    text;
  v_type        text;
  v_lead        text;
  v_answered    boolean;
  v_text        text;
  v_has_options boolean := jsonb_typeof(p -> 'options') = 'array' or p ? 'optionA' or p ? 'optionB';
  v_before      jsonb;
  v_key         jsonb;      -- 20261028100200
  v_regraded    int := 0;   -- 20261028100200
begin
  perform public.adm_require_series_access(public.adm_quiz_series((select quiz_id from public.quiz_questions where id = p_id)), true);   -- 20261028100200: admin or the series' educator
  select quiz_id, question_type into v_quiz, v_cur_lead from public.quiz_questions where id = p_id for update;
  if v_quiz is null then raise exception 'Question not found.' using errcode = 'P0002'; end if;
  perform public.adm_require_quiz(v_quiz);
  v_answered := exists (select 1 from public.quiz_answers where question_id = p_id);
  -- 20261115090000: subjective questions can be edited again (the 20261027090000 read-only check is gone).
  v_before := public.adm_question_json(p_id);
  v_key := public.adm_question_grading_key(p_id);   -- 20261028100200

  if p ? 'type' then
    v_type := lower(btrim(coalesce(p ->> 'type', '')));
    v_lead := public.adm_map_question_type(v_type);
    if v_lead is null then raise exception 'Unsupported question type: %', v_type using errcode = '22023'; end if;
    perform public.adm_assert_question_type_allowed(v_type);
    if v_answered and v_lead <> v_cur_lead then
      raise exception 'Students have answered this question; its type cannot change.' using errcode = '22023';
    end if;
  end if;
  if p ? 'text' or p ? 'body' then
    v_text := nullif(btrim(coalesce(p ->> 'text', p ->> 'body', '')), '');
    if v_text is null then raise exception 'Question text is required.' using errcode = '22023'; end if;
  end if;

  update public.quiz_questions set
    question_text = coalesce(v_text, question_text),
    question_type = coalesce(v_lead, question_type),
    points        = case when p ? 'marks' then coalesce(nullif(p ->> 'marks', '')::numeric, points) else points end,
    explanation   = case when p ? 'explanation' then nullif(btrim(coalesce(p ->> 'explanation', '')), '') else explanation end,
    sort_order    = case when p ? 'position' then coalesce(nullif(p ->> 'position', '')::int, sort_order) else sort_order end
  where id = p_id;

  insert into public.quiz_question_admin (question_id, admin_type)
  values (p_id, public.adm_ui_question_type(v_cur_lead)) on conflict (question_id) do nothing;
  update public.quiz_question_admin set
    admin_type           = coalesce(v_type, admin_type),
    needs_manual_grading = case when v_type is not null then v_type in ('subjective', 'long_answer', 'descriptive') else needs_manual_grading end,
    negative_marks       = case when p ? 'negativeMarks' then greatest(coalesce(nullif(p ->> 'negativeMarks', '')::numeric, 0), 0)
                                when p ? 'negative_marks' then greatest(coalesce(nullif(p ->> 'negative_marks', '')::numeric, 0), 0)
                                else negative_marks end,
    difficulty           = case when lower(coalesce(p ->> 'difficulty', '')) in ('easy', 'medium', 'hard') then lower(p ->> 'difficulty') else difficulty end,
    subject              = case when p ? 'subject' then nullif(btrim(coalesce(p ->> 'subject', '')), '') else subject end,
    topic                = case when p ? 'topic' then nullif(btrim(coalesce(p ->> 'topic', '')), '') else topic end,
    image_path           = case when p ? 'image' or p ? 'image_path'   -- 20261029110000: checked; the current path may stay
                                then public.adm_test_asset_path(coalesce(p ->> 'image', p ->> 'image_path'), 'question_image', array[image_path])
                                else image_path end,
    image_alt            = case when p ? 'imageAlt' or p ? 'image_alt' then left(nullif(btrim(coalesce(p ->> 'imageAlt', p ->> 'image_alt', '')), ''), 300) else image_alt end,
    answer_instructions  = case when p ? 'answerInstructions' then nullif(p ->> 'answerInstructions', '')
                                when p ? 'rubric' then nullif(p ->> 'rubric', '')
                                when p ? 'answer_instructions' then nullif(p ->> 'answer_instructions', '') else answer_instructions end,
    section_id           = case when p ? 'section_id' then nullif(p ->> 'section_id', '')::uuid
                                when p ? 'sectionId' then nullif(p ->> 'sectionId', '')::uuid else section_id end
  where question_id = p_id;

  -- Options are replaced only when the payload carries option texts, when the
  -- question is (or became) a text-answer type, or when its accepted / model
  -- answer changed. Text-answer questions always get exactly one correct
  -- option (accepted answer, model answer or the manual-grading placeholder;
  -- see adm_insert_options), so they stay publishable under the lead's rule.
  if v_has_options or (v_lead is not null and v_lead not in ('multiple_choice', 'true_false'))
     or ((p ? 'correctAnswer' or p ? 'answer' or p ? 'modelAnswer' or p ? 'model_answer')
         and coalesce(v_lead, v_cur_lead) in ('fill_in_blank', 'short_answer')) then
    if v_answered then
      -- 20261028100200: answered: the same options are edited in place (their ids are in
      -- students' answers); adding or removing options is refused.
      perform public.adm_update_options_in_place(p_id, (select question_type from public.quiz_questions where id = p_id),
                                                 p || jsonb_build_object('type', (select admin_type from public.quiz_question_admin
                                                                                   where question_id = p_id)));
    else
      delete from public.quiz_question_options where question_id = p_id;
      perform public.adm_insert_options(p_id, (select question_type from public.quiz_questions where id = p_id),
                                        p || jsonb_build_object('type', (select admin_type from public.quiz_question_admin
                                                                          where question_id = p_id)));
    end if;
  end if;

  -- 20261028100200: marks or the correct answer changed on an answered question: re-score.
  if v_answered and public.adm_question_grading_key(p_id) is distinct from v_key then
    v_regraded := public.adm_regrade_quiz(v_quiz);
  end if;
  perform public.adm_audit('question.update', 'quiz_question', p_id, v_before, public.adm_question_json(p_id), null);
  return public.adm_question_json(p_id) || jsonb_build_object('regraded_attempts', v_regraded);
end $$;

-- adm_copy_quiz: from 20261029110000_admin_test_assets.sql
create or replace function public.adm_copy_quiz(p_src uuid, p_series uuid, p_pos int, p_title text default null) returns uuid
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_new    uuid;
  v_course uuid;
  v_map    jsonb := '{}'::jsonb;
  v_ns     uuid;
  v_nq     uuid;
  sec      record;
  qq       record;
begin
  -- 20261115090000: tests with subjective questions can be copied again.
  select course_id into v_course from public.test_series where id = p_series;
  insert into public.quizzes (course_id, series_id, series_sort_order, title, description, time_limit_mins,
                              max_attempts, passing_score, shuffle_questions, is_required, show_answers_after, is_proctored)
  select v_course, p_series, p_pos, left(coalesce(p_title, q.title), 200), q.description, q.time_limit_mins,
         q.max_attempts, q.passing_score, q.shuffle_questions, q.is_required, q.show_answers_after, q.is_proctored
    from public.quizzes q where q.id = p_src
  returning id into v_new;
  if v_new is null then raise exception 'Test not found.' using errcode = 'P0002'; end if;

  insert into public.quiz_admin (quiz_id, status, total_marks_planned, passing_marks, shuffle_options, window_mode,
                                 open_at, close_at, scheduled_at, planned_questions, topics)
  select v_new, 'draft', total_marks_planned, passing_marks, shuffle_options, window_mode,
         open_at, close_at, scheduled_at, planned_questions, topics
    from public.quiz_admin where quiz_id = p_src;
  insert into public.quiz_admin (quiz_id) values (v_new) on conflict (quiz_id) do nothing;

  for sec in select * from public.test_sections where quiz_id = p_src order by position loop
    insert into public.test_sections (quiz_id, position, name, instructions, planned_questions, planned_marks)
    values (v_new, sec.position, sec.name, sec.instructions, sec.planned_questions, sec.planned_marks)
    returning id into v_ns;
    v_map := v_map || jsonb_build_object(sec.id::text, v_ns);
  end loop;

  for qq in
    select x.id, x.question_text, x.question_type, x.points, x.explanation, x.sort_order,
           qa.admin_type, qa.needs_manual_grading, qa.section_id, qa.negative_marks, qa.difficulty,
           qa.subject, qa.topic, qa.image_path, qa.image_alt, qa.answer_instructions   -- 20261029110000
      from public.quiz_questions x
      left join public.quiz_question_admin qa on qa.question_id = x.id
     where x.quiz_id = p_src
     order by x.sort_order, x.created_at
  loop
    insert into public.quiz_questions (quiz_id, question_text, question_type, points, explanation, sort_order)
    values (v_new, qq.question_text, qq.question_type, qq.points, qq.explanation, qq.sort_order)
    returning id into v_nq;
    insert into public.quiz_question_admin (question_id, admin_type, needs_manual_grading, section_id, negative_marks,
                                            difficulty, subject, topic, image_path, image_alt, answer_instructions, source)
    values (v_nq, coalesce(qq.admin_type, public.adm_ui_question_type(qq.question_type)),
            coalesce(qq.needs_manual_grading, false),
            case when qq.section_id is not null then nullif(v_map ->> qq.section_id::text, '')::uuid end,
            coalesce(qq.negative_marks, 0), coalesce(qq.difficulty, 'medium'), qq.subject, qq.topic,
            qq.image_path, qq.image_alt, qq.answer_instructions, 'duplicate');   -- 20261029110000: the copy keeps the figure
    insert into public.quiz_question_options (question_id, option_text, is_correct, sort_order)
    select v_nq, o.option_text, o.is_correct, o.sort_order
      from public.quiz_question_options o where o.question_id = qq.id;
    -- A text-answer source without a correct option (e.g. one written by the
    -- lead's app) gets the placeholder, so the copy stays publishable.
    if qq.question_type in ('fill_in_blank', 'short_answer')
       and not exists (select 1 from public.quiz_question_options o where o.question_id = v_nq and o.is_correct) then
      insert into public.quiz_question_options (question_id, option_text, is_correct, sort_order)
      values (v_nq, public.adm_text_answer('{}'::jsonb), true,
              coalesce((select max(o.sort_order) from public.quiz_question_options o where o.question_id = v_nq), 0) + 1);
    end if;
  end loop;
  return v_new;
end $$;

-- adm_report_bucket: from 20261026100300_student_rpc_exam.sql
create or replace function public.adm_report_bucket(p_rows jsonb) returns jsonb
language sql immutable set search_path = public, extensions as $$
  -- 20261115090000: 'partial' (an AI-graded written answer with some of its
  -- marks) is a graded answer; it counts towards accuracy by the share of
  -- marks earned. Without partial rows the result is the same as before.
  select jsonb_build_object(
           'total', count(*),
           'attempted', count(*) filter (where r ->> 'status' <> 'skipped'),
           'correct', count(*) filter (where r ->> 'status' = 'correct'),
           'incorrect', count(*) filter (where r ->> 'status' = 'incorrect'),
           'partial', count(*) filter (where r ->> 'status' = 'partial'),
           'skipped', count(*) filter (where r ->> 'status' = 'skipped'),
           'pending', count(*) filter (where r ->> 'status' = 'pending'),
           'graded', count(*) filter (where r ->> 'status' in ('correct', 'incorrect', 'partial')),
           'accuracy', coalesce(round((count(*) filter (where r ->> 'status' = 'correct')
                                       + coalesce(sum(greatest((r ->> 'points_earned')::numeric, 0) / nullif((r ->> 'points')::numeric, 0))
                                                    filter (where r ->> 'status' = 'partial'), 0)) * 100.0
                                      / nullif(count(*) filter (where r ->> 'status' in ('correct', 'incorrect', 'partial')), 0), 1), 0),
           'marks_earned', coalesce(sum((r ->> 'points_earned')::numeric), 0),
           'marks_possible', coalesce(sum((r ->> 'points')::numeric) filter (where r ->> 'status' <> 'pending'), 0))
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) r;
$$;

-- ------------------------------------------------------- evaluation jobs
create table public.ai_attempt_evaluations (
  attempt_id    uuid primary key references public.quiz_attempts(id) on delete cascade,
  status        text not null default 'queued' check (status in ('queued', 'running', 'done', 'failed')),
  tries         int not null default 0,
  model         text,
  questions     jsonb,          -- the AI's per-question results, as saved
  overall       jsonb,          -- the AI's overall feedback
  error         text,           -- internal; students see a generic message
  input_tokens  int,
  output_tokens int,
  queued_at     timestamptz not null default now(),
  started_at    timestamptz,
  completed_at  timestamptz
);
create index ai_attempt_evaluations_status_idx on public.ai_attempt_evaluations (status, started_at);
alter table public.ai_attempt_evaluations enable row level security;   -- no policies: RPCs only
revoke all on table public.ai_attempt_evaluations from public, anon, authenticated;

-- The report rows still waiting for a grade that AI can grade (written answers).
create or replace function public.adm_ai_pending_question_ids(p_report jsonb) returns uuid[]
language sql stable security definer set search_path = public, extensions as $$
  select coalesce(array_agg((r ->> 'question_id')::uuid), '{}')
    from jsonb_array_elements(coalesce(p_report -> 'questions', '[]'::jsonb)) r
   where r ->> 'status' = 'pending' and public.adm_question_is_subjective((r ->> 'question_id')::uuid);
$$;

-- Student (report page / evaluate-subjective): claim the evaluation of my
-- attempt. {status, claimed}: claimed = true means "you run it now".
create or replace function public.student_ai_eval_request(p_attempt_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_uid    uuid := public.adm_student_uid();
  v_owner  uuid;
  v_report jsonb;
  e        public.ai_attempt_evaluations%rowtype;
begin
  select student_id into v_owner from public.quiz_attempts where id = p_attempt_id;
  if v_owner is null or v_owner <> v_uid then
    raise exception 'Attempt not found.' using errcode = 'P0002';
  end if;
  select report into v_report from public.attempt_reports where attempt_id = p_attempt_id;
  if v_report is null then
    return jsonb_build_object('status', 'not_ready', 'claimed', false);
  end if;
  insert into public.ai_attempt_evaluations (attempt_id) values (p_attempt_id) on conflict (attempt_id) do nothing;
  select * into e from public.ai_attempt_evaluations where attempt_id = p_attempt_id for update;
  if e.status = 'done' then
    return jsonb_build_object('status', 'done', 'claimed', false);
  end if;
  if cardinality(public.adm_ai_pending_question_ids(v_report)) = 0 then
    update public.ai_attempt_evaluations set status = 'done', completed_at = now() where attempt_id = p_attempt_id;
    return jsonb_build_object('status', 'not_needed', 'claimed', false);
  end if;
  if e.status = 'running' and e.started_at > now() - interval '3 minutes' then
    return jsonb_build_object('status', 'running', 'claimed', false);
  end if;
  if e.tries >= 3 then
    update public.ai_attempt_evaluations set status = 'failed', completed_at = coalesce(completed_at, now())
     where attempt_id = p_attempt_id and status <> 'failed';
    return jsonb_build_object('status', 'failed', 'claimed', false, 'can_retry', false);
  end if;
  update public.ai_attempt_evaluations
     set status = 'running', tries = tries + 1, started_at = now(), error = null, completed_at = null
   where attempt_id = p_attempt_id;
  return jsonb_build_object('status', 'running', 'claimed', true);
end $$;

-- Student: progress of my attempt's evaluation.
create or replace function public.student_ai_eval_status(p_attempt_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  v_uid   uuid := public.adm_student_uid();
  v_owner uuid;
  e       public.ai_attempt_evaluations%rowtype;
  v_stale boolean;
begin
  select student_id into v_owner from public.quiz_attempts where id = p_attempt_id;
  if v_owner is null or v_owner <> v_uid then
    raise exception 'Attempt not found.' using errcode = 'P0002';
  end if;
  select * into e from public.ai_attempt_evaluations where attempt_id = p_attempt_id;
  if e.attempt_id is null then
    return jsonb_build_object('status', 'none', 'can_retry', true);
  end if;
  v_stale := e.status = 'running' and e.started_at <= now() - interval '3 minutes';
  return jsonb_build_object(
    'status', case when v_stale then 'failed' else e.status end,
    'tries', e.tries,
    'can_retry', (e.status = 'failed' or v_stale) and e.tries < 3,
    'completed_at', e.completed_at);
end $$;

-- Service role (evaluate-subjective): what the AI needs, and nothing else.
create or replace function public.adm_ai_eval_context(p_attempt_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  v_report jsonb;
  v_ids    uuid[];
begin
  select report into v_report from public.attempt_reports where attempt_id = p_attempt_id;
  if v_report is null then raise exception 'No report for this attempt.' using errcode = 'P0002'; end if;
  v_ids := public.adm_ai_pending_question_ids(v_report);
  return jsonb_build_object(
    'attempt_id', p_attempt_id,
    'test_title', v_report ->> 'test_title',
    'series_title', v_report ->> 'series_title',
    'reveal_answers', not coalesce((v_report #>> '{summary,answers_hidden}')::boolean, false),
    'questions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'question_id', qq.id,
               'position', (r ->> 'position')::int,
               'type', coalesce(qa.admin_type, qq.question_type),
               'question', qq.question_text,
               'max_marks', qq.points,
               'model_answer', (select string_agg(o.option_text, ' / ' order by o.sort_order, o.id)
                                  from public.quiz_question_options o
                                 where o.question_id = qq.id and o.is_correct
                                   and o.option_text <> 'Manual grading: see rubric'),
               'marking_guide', nullif(btrim(coalesce(qa.answer_instructions, '')), ''),
               'explanation', nullif(btrim(coalesce(qq.explanation, '')), ''),
               'topic', qa.topic,
               'student_answer', (select ans.answer_text from public.quiz_answers ans
                                   where ans.attempt_id = p_attempt_id and ans.question_id = qq.id
                                   order by ans.created_at desc limit 1))
             order by (r ->> 'position')::int)
        from jsonb_array_elements(v_report -> 'questions') r
        join public.quiz_questions qq on qq.id = (r ->> 'question_id')::uuid
        left join public.quiz_question_admin qa on qa.question_id = qq.id
       where qq.id = any (v_ids)), '[]'::jsonb));
end $$;

-- Service role: apply the AI's grades to the attempt and its report.
-- p_result = {questions: [{question_id, marks_awarded, verdict, feedback,
--   strengths[], improvements[], key_points_missed[]}], overall: {summary,
--   strengths[], areas_to_improve[], study_tips[]}}
create or replace function public.adm_ai_eval_complete(
  p_attempt_id uuid, p_result jsonb, p_model text default null,
  p_input_tokens int default null, p_output_tokens int default null
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  e        public.ai_attempt_evaluations%rowtype;
  v_att    record;
  v_report jsonb;
  v_rows   jsonb := '[]'::jsonb;
  r        jsonb;
  res      jsonb;
  v_pts    numeric;
  v_earned numeric;
  v_state  text;
  v_n      int := 0;
  v_score  numeric;
  v_max    numeric;
  v_pct    numeric;
  v_pass   numeric;
  v_passed boolean;
  v_cmp    record;
  v_rank   int;
  v_lower  int;
  v_ids    uuid[];
begin
  select * into e from public.ai_attempt_evaluations where attempt_id = p_attempt_id for update;
  if e.attempt_id is null or e.status <> 'running' then
    raise exception 'This evaluation is not running.' using errcode = '22023';
  end if;
  select a.* into v_att from public.quiz_attempts a where a.id = p_attempt_id for update;
  select report into v_report from public.attempt_reports where attempt_id = p_attempt_id for update;
  if v_report is null then raise exception 'No report for this attempt.' using errcode = 'P0002'; end if;
  v_ids := public.adm_ai_pending_question_ids(v_report);

  for r in select x from jsonb_array_elements(v_report -> 'questions') x order by (x ->> 'position')::int loop
    res := null;
    if r ->> 'status' = 'pending' and (r ->> 'question_id')::uuid = any (v_ids) then
      select x into res from jsonb_array_elements(coalesce(p_result -> 'questions', '[]'::jsonb)) x
       where x ->> 'question_id' = r ->> 'question_id' limit 1;
    end if;
    if res is not null and jsonb_typeof(res -> 'marks_awarded') = 'number' then
      v_pts    := coalesce((r ->> 'points')::numeric, 0);
      v_earned := least(greatest(round((res ->> 'marks_awarded')::numeric, 2), 0), v_pts);
      v_state  := case when v_earned >= v_pts and v_pts > 0 then 'correct' when v_earned <= 0 then 'incorrect' else 'partial' end;
      r := r || jsonb_build_object(
        'status', v_state,
        'points_earned', v_earned,
        'ai_evaluation', jsonb_build_object(
          'marks_awarded', v_earned,
          'verdict', left(coalesce(res ->> 'verdict', ''), 40),
          'feedback', left(coalesce(res ->> 'feedback', ''), 2000),
          'strengths', coalesce(res -> 'strengths', '[]'::jsonb),
          'improvements', coalesce(res -> 'improvements', '[]'::jsonb),
          'key_points_missed', coalesce(res -> 'key_points_missed', '[]'::jsonb)));
      update public.quiz_answers
         set points_earned = v_earned, is_correct = (v_earned >= v_pts and v_pts > 0)
       where attempt_id = p_attempt_id and question_id = (r ->> 'question_id')::uuid;
      v_n := v_n + 1;
    end if;
    v_rows := v_rows || jsonb_build_array(r);
  end loop;

  -- score over every graded row (as adm_finalize_attempt does)
  select coalesce(sum(coalesce((x ->> 'points_earned')::numeric, 0)) filter (where x ->> 'status' <> 'pending'), 0),
         coalesce(sum((x ->> 'points')::numeric) filter (where x ->> 'status' <> 'pending'), 0)
    into v_score, v_max
    from jsonb_array_elements(v_rows) x;
  v_pass   := coalesce((v_report #>> '{summary,passing_percentage}')::numeric, 0);
  v_pct    := case when v_max > 0 then greatest(round(v_score * 100.0 / v_max, 2), 0) else 0 end;
  v_passed := v_pct >= v_pass;

  update public.quiz_attempts set score = v_score, max_score = v_max, percentage = v_pct, passed = v_passed
   where id = p_attempt_id;

  select count(*) as n, round(avg(a.percentage), 2) as avg_pct, max(a.percentage) as top_pct,
         round(avg(a.score), 2) as avg_score, max(a.score) as top_score
    into v_cmp
    from public.quiz_attempts a
   where a.quiz_id = v_att.quiz_id and a.status in ('submitted', 'timed_out') and a.percentage is not null;
  select count(*) filter (where a.percentage > v_pct) + 1, count(*) filter (where a.percentage < v_pct)
    into v_rank, v_lower
    from public.quiz_attempts a
   where a.quiz_id = v_att.quiz_id and a.status in ('submitted', 'timed_out') and a.percentage is not null;

  v_report := v_report || jsonb_build_object(
    'questions', v_rows,
    'summary', (v_report -> 'summary') || jsonb_build_object(
      'score', v_score, 'max_score', v_max, 'percentage', v_pct, 'passed', v_passed,
      'correct_count', (select count(*) from jsonb_array_elements(v_rows) x where x ->> 'status' = 'correct'),
      'incorrect_count', (select count(*) from jsonb_array_elements(v_rows) x where x ->> 'status' = 'incorrect'),
      'partial_count', (select count(*) from jsonb_array_elements(v_rows) x where x ->> 'status' = 'partial'),
      'pending_count', (select count(*) from jsonb_array_elements(v_rows) x where x ->> 'status' = 'pending'),
      'pending_marks', (select coalesce(sum((x ->> 'points')::numeric), 0) from jsonb_array_elements(v_rows) x where x ->> 'status' = 'pending'),
      'provisional', exists (select 1 from jsonb_array_elements(v_rows) x where x ->> 'status' = 'pending'),
      'ai_evaluated', true,
      'rank', v_rank,
      'total_attempts', v_cmp.n,
      'percentile', case when v_cmp.n > 1 then round(v_lower * 100.0 / (v_cmp.n - 1), 1) else 100 end,
      'class_average', coalesce(v_cmp.avg_pct, 0),
      'topper_percentage', coalesce(v_cmp.top_pct, 0)),
    'breakdowns', jsonb_build_object(
      'by_section', (select coalesce(jsonb_agg(b order by (b ->> 'position')::int, b ->> 'name'), '[]'::jsonb) from (
                       select jsonb_build_object('name', x ->> 'section', 'position', min((x ->> 'section_position')::int))
                              || public.adm_report_bucket(jsonb_agg(x)) as b
                         from jsonb_array_elements(v_rows) x group by x ->> 'section') s),
      'by_topic', (select coalesce(jsonb_agg(b order by b ->> 'name'), '[]'::jsonb) from (
                     select jsonb_build_object('name', x ->> 'topic') || public.adm_report_bucket(jsonb_agg(x)) as b
                       from jsonb_array_elements(v_rows) x group by x ->> 'topic') s),
      'by_difficulty', (select coalesce(jsonb_agg(b order by case b ->> 'name' when 'easy' then 1 when 'medium' then 2
                                                                                 when 'hard' then 3 else 4 end), '[]'::jsonb) from (
                          select jsonb_build_object('name', x ->> 'difficulty') || public.adm_report_bucket(jsonb_agg(x)) as b
                            from jsonb_array_elements(v_rows) x group by x ->> 'difficulty') s)),
    'comparison', (v_report -> 'comparison') || jsonb_build_object(
      'your_percentage', v_pct,
      'average_percentage', coalesce(v_cmp.avg_pct, 0),
      'topper_percentage', coalesce(v_cmp.top_pct, 0),
      'your_score', v_score,
      'average_score', coalesce(v_cmp.avg_score, 0),
      'topper_score', coalesce(v_cmp.top_score, 0),
      'difference_from_average', round(v_pct - coalesce(v_cmp.avg_pct, 0), 2),
      'difference_from_topper', round(v_pct - coalesce(v_cmp.top_pct, 0), 2)),
    'ai', jsonb_build_object(
      'status', 'done',
      'model', p_model,
      'evaluated_at', now(),
      'evaluated_count', v_n,
      'summary', left(coalesce(p_result #>> '{overall,summary}', ''), 3000),
      'strengths', coalesce(p_result #> '{overall,strengths}', '[]'::jsonb),
      'areas_to_improve', coalesce(p_result #> '{overall,areas_to_improve}', '[]'::jsonb),
      'study_tips', coalesce(p_result #> '{overall,study_tips}', '[]'::jsonb)));

  v_report := v_report || jsonb_build_object(
    'strengths', (select coalesce(jsonb_agg(jsonb_build_object('topic', t ->> 'name', 'accuracy', (t ->> 'accuracy')::numeric)
                                            order by (t ->> 'accuracy')::numeric desc, t ->> 'name'), '[]'::jsonb)
                    from (select t from jsonb_array_elements(v_report #> '{breakdowns,by_topic}') t
                           where (t ->> 'graded')::int > 0 and (t ->> 'accuracy')::numeric >= 60
                           order by (t ->> 'accuracy')::numeric desc, t ->> 'name' limit 3) s),
    'weaknesses', (select coalesce(jsonb_agg(jsonb_build_object('topic', t ->> 'name', 'accuracy', (t ->> 'accuracy')::numeric)
                                             order by (t ->> 'accuracy')::numeric, t ->> 'name'), '[]'::jsonb)
                     from (select t from jsonb_array_elements(v_report #> '{breakdowns,by_topic}') t
                            where (t ->> 'graded')::int > 0 and (t ->> 'accuracy')::numeric < 60
                            order by (t ->> 'accuracy')::numeric, t ->> 'name' limit 3) s));

  update public.attempt_reports set report = v_report where attempt_id = p_attempt_id;
  update public.ai_attempt_evaluations
     set status = 'done', model = p_model, questions = p_result -> 'questions', overall = p_result -> 'overall',
         input_tokens = p_input_tokens, output_tokens = p_output_tokens, error = null, completed_at = now()
   where attempt_id = p_attempt_id;
  return jsonb_build_object('status', 'done', 'graded', v_n, 'score', v_score, 'max_score', v_max, 'percentage', v_pct);
end $$;

-- Service role: the evaluation failed (the student can try again, up to 3 tries).
create or replace function public.adm_ai_eval_fail(p_attempt_id uuid, p_error text) returns void
language sql security definer set search_path = public, extensions as $$
  update public.ai_attempt_evaluations
     set status = 'failed', error = left(coalesce(p_error, 'unknown error'), 1000), completed_at = now()
   where attempt_id = p_attempt_id and status = 'running';
$$;

-- ------------------------------------------------------------------ grants
revoke all on function public.adm_ai_pending_question_ids(jsonb) from public, anon, authenticated;
revoke all on function public.student_ai_eval_request(uuid) from public, anon;
revoke all on function public.student_ai_eval_status(uuid) from public, anon;
revoke all on function public.adm_ai_eval_context(uuid) from public, anon, authenticated;
revoke all on function public.adm_ai_eval_complete(uuid, jsonb, text, int, int) from public, anon, authenticated;
revoke all on function public.adm_ai_eval_fail(uuid, text) from public, anon, authenticated;
grant execute on function public.student_ai_eval_request(uuid) to authenticated;
grant execute on function public.student_ai_eval_status(uuid) to authenticated;
grant execute on function public.adm_ai_eval_context(uuid) to service_role;
grant execute on function public.adm_ai_eval_complete(uuid, jsonb, text, int, int) to service_role;
grant execute on function public.adm_ai_eval_fail(uuid, text) to service_role;
